/bin/bash -lc "mkdir -p /tmp/pulse-check && node --input-type=module <<'JS'
import { chromium } from 'playwright';
const browser = await chromium.launch({headless:true, args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:1050},deviceScaleFactor:1});
const errors=[];page.on('pageerror',error=>errors.push(error.message));
await page.goto('http://localhost:5174/', {waitUntil:'networkidle'});
await page.screenshot({path:'/tmp/pulse-check/desktop.png',fullPage:true});
console.log(JSON.stringify({errors,chart:await page.locator('.chart-canvas').innerText(),bodyHeight:await page.locator('body').evaluate(el=>el.scrollHeight)},null,2));
await page.getByRole('tab',{name:'Мониторинг'}).click();
await page.waitForTimeout(1700);
await page.screenshot({path:'/tmp/pulse-check/monitoring.png',fullPage:true});
console.log(JSON.stringify({errors,monitoring:await page.locator('.chart-canvas').innerText(),canvasCount:await page.locator('.chart-canvas canvas').count()},null,2));
await page.setViewportSize({width:390,height:844});
await page.getByRole('tab',{name:'Продажи'}).click();
await page.waitForTimeout(500);
await page.screenshot({path:'/tmp/pulse-check/mobile.png',fullPage:true});
console.log(JSON.stringify({mobileOverflow:await page.evaluate(()=>document.documentElement.scrollWidth > innerWidth),errors},null,2));
await browser.close();
JS"

