import type { RadarSeries, RadarSeriesData } from './radar';
import type { SankeySeries, SankeySeriesData } from './sankey';
import type { ScatterSeries, ScatterSeriesData } from './scatter';
import type { TreemapSeries, TreemapSeriesData } from './treemap';
import type { WaterfallSeries, WaterfallSeriesData } from './waterfall';
import type { XRangeSeries, XRangeSeriesData } from './x-range';
export type ChartSeries<T = MeaningfulAny> = ScatterSeries<T> | PieSeries<T> | BarXSeries<T> | BarYSeries<T> | LineSeries<T> | AreaSeries<T> | AreaRangeSeries<T> | TreemapSeries<T> | WaterfallSeries<T> | SankeySeries<T> | RadarSeries<T> | HeatmapSeries<T> | FunnelSeries<T> | XRangeSeries<T>;
export type ChartSeriesData<T = MeaningfulAny> = ScatterSeriesData<T> | PieSeriesData<T> | BarXSeriesData<T> | BarYSeriesData<T> | LineSeriesData<T> | AreaSeriesData<T> | AreaRangeSeriesData<T> | TreemapSeriesData<T> | WaterfallSeriesData<T> | SankeySeriesData<T> | RadarSeriesData<T> | HeatmapSeriesData<T> | FunnelSeriesData<T> | XRangeSeriesData<T>;
export interface DataLabelRendererData<T = MeaningfulAny> {
    data: ChartSeriesData<T>;
}
export interface BasicHoverState {
    /**
     * Enable separate styles for the hovered series.
     * @default true
     */
    enabled?: boolean;
    /**
     * How much to brighten/darken the point on hover. Use positive to brighten, negative to darken.
     * The behavior of this property is dependent on the implementing color space ([more details](https://d3js.org/d3-color#color_brighter)).
     * For example in case of using rgb color you can use floating point number from `-5.0` to `5.0`.
     * Rgb color space is used by default.
     * @default 0.3
     */
    brightness?: number;
}
export interface BasicInactiveState {
    /**
     * Enable separate styles for the inactive series.
     * @default false for most series types; true for radar
     */
    enabled?: boolean;
    /**
     * Opacity of series elements (bars, data labels)
     * @default 0.5
     */
    opacity?: number;
}
/**
 * Raw totals of visible stacked series. Participants in one stack and value axis must
 * resolve to identical style, format, padding and allowOverlap settings or validation fails.
 */
export interface StackLabelsOptions {
    /**
     * Include the visible series in stack totals. Series-level values override plugin options.
     * @default false
     */
    enabled?: boolean;
    /** Format the raw sum, including for percent stacks. Custom formatters receive `{value}`. */
    format?: ValueFormat;
    /** Text styles, merged with plugin defaults. */
    style?: Partial<BaseTextStyle>;
    /**
     * Distance from the stack boundary in pixels. Labels are kept inside the plot.
     * @default 5
     */
    padding?: number;
    /**
     * Allow totals to overlap other labels. Otherwise overlapping totals are hidden.
     * Segment labels in the same plugin layer take priority, even for small top segments.
     * @default false
     */
    allowOverlap?: boolean;
