import { chromium } from 'playwright';
const browser = await chromium.launch({headless:true, args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:1050},deviceScaleFactor:1});
const errors=[];page.on('pageerror',error=>errors.push(error.message));
await page.goto('http://localhost:5174/', {waitUntil:'networkidle'});
await page.screenshot({path:'/tmp/pulse-check/desktop.png',fullPage:true});
console.log(JSON.stringify({errors,chart:await page.locator('.chart-canvas').innerText(),bodyHeight:await page.locator('body').evaluate(el=>el.scrollHeight)},null,2));
