await page.waitForTimeout(1700);
await page.screenshot({path:'/tmp/pulse-check/monitoring.png',fullPage:true});
console.log(JSON.stringify({errors,monitoring:await page.locator('.chart-canvas').innerText(),canvasCount:await page.locator('.chart-canvas canvas').count()},null,2));
await page.setViewportSize({width:390,height:844});
await page.getByRole('tab',{name:'Продажи'}).click();
await page.waitForTimeout(500);
await page.screenshot({path:'/tmp/pulse-check/mobile.png',fullPage:true});
console.log(JSON.stringify({mobileOverflow:await page.evaluate(()=>document.documentElement.scrollWidth > innerWidth),errors},null,2));
await browser.close();
JS"

