import type {ChartEngineProps} from './types';

settings.set({plugins: [GravityChartsPlugin], lang: 'ru'});
export default function SalesEngine({points, comparison}: ChartEngineProps) {
    return <ChartKit type="gravity-charts" data={{
        chart: {margin: {top: 15, right: 15, bottom: 5, left: 5}},
        series: {data: [
            ...(comparison ? [{type: 'line' as const, name: 'Предыдущий период', color: '#c5ccd2', dashStyle: 'Dash' as const, lineWidth: 2, interpolation: {type: 'monotone' as const}, data: points.map(p => ({x: p.timestamp, y: p.previous}))}] : []),
            {type: 'area', name: 'Текущий период', color: '#269c78', lineWidth: 2.5, fillColor: {type: 'linear-gradient', angle: 180, stops: [{offset: 0, color: 'rgba(38, 156, 120, 0.16)'}, {offset: 1, color: 'rgba(38, 156, 120, 0.005)'}]}, data: points.map(p => ({x: p.timestamp, y: p.value}))},
        ]},
        xAxis: {type: 'datetime', lineVisible: false, grid: {enabled: false}, ticks: {values: points.filter((_, i) => i % Math.max(1, Math.ceil(points.length / 6)) === 0 || i === points.length - 1).map(point => point.timestamp)}, labels: {dateFormat: points.length === 24 ? 'HH:mm' : 'DD.MM', style: {fontSize: '11px'}}},
        yAxis: [{lineVisible: false, min: 0, max: Math.ceil(Math.max(...points.map(p => p.value)) / 40000) * 40000, ticks: {pixelInterval: 62}, labels: {numberFormat: {precision: 0, units: {factor: 1000, postfix: 'тыс. ₽'}}, style: {fontSize: '11px'}}}],
        legend: {enabled: false},
        tooltip: {headerFormat: {type: 'custom', formatter: ({value}) => new Date(Number(value)).toLocaleDateString('ru-RU', {day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC'})}, valueFormat: {type: 'number', precision: 0, postfix: ' ₽', showRankDelimiter: true}},
    }} />;
}
export type ChartMode = 'sales' | 'monitoring';
export type Period = 'day' | 'week' | 'month' | 'year';
export interface ChartPoint { timestamp: number; value: number; previous: number }
export interface ChartEngineProps { points: ChartPoint[]; comparison: boolean }
export const periodLabels: Record<Period, string> = {day: 'День', week: 'Неделя', month: 'Месяц', year: 'Год'};
export const money = (value: number) => new Intl.NumberFormat('ru-RU', {maximumFractionDigits: 0}).format(value) + ' ₽';
export function createPoints(mode: ChartMode, period: Period, end: number, multiplier = 1): ChartPoint[] {
    const duration = {day: 86400000, week: 7 * 86400000, month: 30 * 86400000, year: 365 * 86400000}[period];
    const count = mode === 'monitoring' ? 2400 : period === 'day' ? 24 : period === 'year' ? 52 : period === 'week' ? 7 : 30;
    const shape = [44, 49, 46, 58, 52, 40, 46, 64, 61, 62, 50, 56, 75, 79, 70, 88, 82, 79, 84, 71, 77, 96, 93, 110, 98, 108, 94, 102, 119, 112];
    const phase = mode === 'monitoring' ? Math.floor(end / 4000) % 1000 : 0;
    const points = Array.from({length: count}, (_, i) => {
        const t = i / (count - 1);
        const value = mode === 'sales' ? shape[Math.round(t * 29)] * 1000 * multiplier : (186 + 22 * Math.sin((i + phase) * .021) + 12 * Math.sin((i + phase) * .19) + 8 * Math.sin((i + phase) * 1.73) + ((i + phase) % 331 < 6 ? 65 : 0)) * multiplier;
        return {timestamp: Math.round(end - duration + 60000 + t * (duration - 60000)), value: Math.round(value), previous: Math.round(value * (.77 + .12 * Math.sin(i * .7 + 2)))};
    });
    if (mode === 'sales') {
        const total = points.reduce((sum, point) => sum + point.value, 0);
        const previous = points.reduce((sum, point) => sum + point.previous, 0);
        for (const point of points) point.previous = Math.round(point.previous * total / (previous * 1.186));
    }
    return points;
}
