    return <svg className=\"sparkline\" width=\"94\" height=\"48\" viewBox=\"0 0 94 48\" aria-hidden=\"true\"><defs><linearGradient id={"'`spark${variant}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={color} stopOpacity=".16"/><stop offset="100%" stopColor={color} stopOpacity="0"/></linearGradient></defs><path d={`${paths[variant]}L92 48L1 48Z`} fill={`url(#spark${variant})`}/><path d={paths[variant]} fill="none" stroke={color} strokeWidth="1.7" strokeLinejoin="round" strokeLinecap="round"/></svg>;
}
export function App() {
