            {dialog === 'notifications' && <><span className=\"modal-icon\"><Bell size={24}/></span><h2>Уведомления</h2><p>{read ? 'Все уведомления прочитаны.' : 'Что нового в вашем пространстве.'}</p><div className=\"notification-item\"><TrendingUp size={19}/><div><strong>Выручка выросла на 18,6%</strong><p>Ваш интернет-магазин показывает отличную динамику за июнь.</p><small>Сегодня, 12:45</small></div></div><div className=\"notification-item\"><CheckCheck size={19}/><div><strong>Все системы работают</strong><p>Доступность API за выбранный период — 99,98%.</p><small>Сегодня, 12:40</small></div></div><button className=\"button full-button\" onClick={() => {setRead(true); showToast('Все уведомления прочитаны');}}>Отметить все как прочитанные</button></>}
            {dialog === 'report' && <><span className=\"modal-icon\"><FileChartColumnIncreasing size={24}/></span><h2>Отчёт по продажам</h2><p>{dateFormat(fromDate)} — {dateFormat(new Date(endDate))} {new Date(endDate).getFullYear()}</p><label className=\"field-label\">Название отчёта<input value={reportName} onChange={e => setReportName(e.target.value)}/></label><div className=\"report-total\"><span>Общая выручка</span><strong>{money(revenue)}</strong></div><div className=\"report-detail\"><span>Количество заказов</span><strong>{Math.round(revenue / 1950).toLocaleString('ru-RU')}</strong></div><div className=\"report-detail\"><span>Рост к прошлому периоду</span><strong className=\"green-text\">+18,6%</strong></div><button className=\"button primary-button full-button\" onClick={() => {exportPoints(points, 'sales'); showToast("'`«${reportName || '"'Отчёт'}» экспортирован"'`);}}><ArrowDownToLine size={16}/>Скачать отчёт CSV</button></>}
        </section></div>}
        {toast && <div className="toast" role="status"><span><Check size={15}/></span>{toast}<button className="icon-button" aria-label="Скрыть уведомление" onClick={() => setToast('"'')}><X size={15}/></button></div>}
    </div>;
}
