test('updates monitoring data and freezes it when paused', async ({page}) => {
  await page.clock.install();
  await page.goto('/');
  await page.getByRole('tab', {name: 'Мониторинг'}).click();
  const canvas = page.locator('.chart-canvas canvas');
  await expect(canvas).toBeVisible();
  await page.evaluate(() => document.fonts.ready);
  const initial = await canvas.evaluate((el: HTMLCanvasElement) => el.toDataURL());
  await page.clock.fastForward(4100);
  await expect.poll(() => canvas.evaluate((el: HTMLCanvasElement) => el.toDataURL())).not.toBe(initial);
  await page.getByRole('button', {name: 'Пауза', exact: true}).click();
  const paused = await canvas.evaluate((el: HTMLCanvasElement) => el.toDataURL());
  await page.clock.fastForward(8100);
  expect(await canvas.evaluate((el: HTMLCanvasElement) => el.toDataURL())).toBe(paused);
  await page.getByRole('button', {name: 'Продолжить'}).click();
  await page.clock.fastForward(4100);
  await expect.poll(() => canvas.evaluate((el: HTMLCanvasElement) => el.toDataURL())).not.toBe(paused);
});
